import{_ as a,o as l,c as s,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/schueler/tutorials-flucht-1-staat.png",d="/bilder/schueler/tutorials-flucht-2-jahrgang.png",u="/bilder/schueler/tutorials-flucht-3-individualdaten-ii.png",h="/bilder/schueler/tutorials-flucht-schule-aus-ausland.png",o="/bilder/schueler/tutorials-flucht-schule-aus-ausland-hinzufuegen.png",g="/bilder/schueler/tutorials-flucht-5-klasse-anlegen.png",c="/bilder/schueler/tutorials-flucht-4-klassenart.png",_=JSON.parse('{"title":"Geflüchtete Kinder und Jugendliche erfassen","description":"","frontmatter":{"title":"Geflüchtete Kinder und Jugendliche erfassen","source_pageid":792,"source_revision":5487},"headers":[],"relativePath":"schild3/schueler/eingabe-von-fluechtlingskindern-tutorial.md","filePath":"schild3/schueler/eingabe-von-fluechtlingskindern-tutorial.md"}'),m={name:"schild3/schueler/eingabe-von-fluechtlingskindern-tutorial.md"};function f(p,r,k,b,S,z){return l(),s("div",null,[...r[0]||(r[0]=[i('<h1 id="gefluchtete-kinder-und-jugendliche-erfassen" tabindex="-1">Geflüchtete Kinder und Jugendliche erfassen <a class="header-anchor" href="#gefluchtete-kinder-und-jugendliche-erfassen" aria-label="Permalink to &quot;Geflüchtete Kinder und Jugendliche erfassen&quot;">​</a></h1><p>Erfassen Sie Individualdaten, Herkunft, Förderung und Klassenzuordnung geflüchteter Kinder und Jugendlicher. Die Anleitung unterscheidet Einzelklassen, Regelklassen und Besonderheiten der Grundschule.</p><p>Erfassen Sie die tatsächlichen Personen-, Schulbesuchs- und Förderangaben. Die folgenden Herkunftseinträge sind ein Beispiel für eine unmittelbare Aufnahme aus dem Ausland. Bei einem Wechsel aus einer anderen deutschen Schule ist deren tatsächlicher Schulbesuch zu erfassen.</p><h2 id="individualdaten" tabindex="-1">Individualdaten <a class="header-anchor" href="#individualdaten" aria-label="Permalink to &quot;Individualdaten&quot;">​</a></h2><h3 id="individualdaten-i" tabindex="-1">Individualdaten I <a class="header-anchor" href="#individualdaten-i" aria-label="Permalink to &quot;Individualdaten I&quot;">​</a></h3><p>Tragen Sie die Individualdaten wie gewohnt nach besten Wissen ein.</p><p><a href="/bilder/schueler/tutorials-flucht-1-staat.png"><img src="'+t+'" alt="Eintragung der Staatsangehörigkeit." loading="lazy"></a></p><p><em>Eintragung der Staatsangehörigkeit.</em></p><ul><li><strong>Staatsangehörigkeit(en)</strong>: Übernehmen Sie die tatsächlichen Angaben aus den vorliegenden Unterlagen. Eine Flucht- oder Zuwanderungsgeschichte ist kein Grund, eine vorhandene deutsche Staatsangehörigkeit wegzulassen. Bei mehreren Staatsangehörigkeiten mit deutscher Staatsangehörigkeit steht diese an erster Stelle; siehe <a href="/schild3/schueler/individualdaten-i-schueler.html">Individualdaten I</a>.</li><li><strong>Aufnahmedatum</strong>: Tag der Aufnahme, also z.B. den 19.06.2024</li></ul><p><a href="/bilder/schueler/tutorials-flucht-2-jahrgang.png"><img src="'+d+'" alt="Eintragung eines passenden Jahrgangs." loading="lazy"></a></p><p><em>Eintragung eines passenden Jahrgangs.</em></p><ul><li><strong>Statistik-Jahrgang</strong>: Erfassen Sie die zutreffende schulische Zuordnung im <strong>aktuellen Lernabschnitt</strong>. Die aktuellen Laufbahndaten in Individualdaten I zeigen diese an. Verwenden Sie nicht allein das Alter als Zuordnungskriterium.</li></ul><h3 id="individualdaten-ii" tabindex="-1">Individualdaten II <a class="header-anchor" href="#individualdaten-ii" aria-label="Permalink to &quot;Individualdaten II&quot;">​</a></h3><p><a href="/bilder/schueler/tutorials-flucht-3-individualdaten-ii.png"><img src="'+u+'" alt="Eintragen des Migrationshintergrunds in Individualdaten II." loading="lazy"></a></p><p><em>Eintragen des Migrationshintergrunds in Individualdaten II.</em></p><p>Unter <em>Migrationshintergrund</em> können Daten zur Herkunft und der Verkehrssprache in der Familie aufgenommen werden.</p><p>Setzen Sie den Haken bei <strong>Migrationshintergrund vorhanden</strong>.</p><p>Tragen Sie bei Bedarf das <strong>Datum Ende der Eingliederungsphase</strong> ein. Dieses Datum wird automatisch auch in <strong>Ende Erstförderung</strong> eingetragen. Mit <strong>Filter I</strong> können Sie anschließend nach diesen Angaben filtern.</p><p>Zudem können Sie das Häkchen <strong>Neu zugewandert</strong> setzen, das sich ebenfalls über den <em>Filter I</em> nutzen lässt.</p><h2 id="vorheriger-schulbesuch" tabindex="-1">Vorheriger Schulbesuch <a class="header-anchor" href="#vorheriger-schulbesuch" aria-label="Permalink to &quot;Vorheriger Schulbesuch&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-flucht-schule-aus-ausland.png"><img src="'+h+'" alt="Eintragung der vorherigen Schule unter Schüler ➜ Schulbesuch: &quot;Schule aus dem sonstigen Ausland&quot;." loading="lazy"></a></p><p><em>Eintragung der vorherigen Schule unter Schüler ➜ Schulbesuch: &quot;Schule aus dem sonstigen Ausland&quot;.</em></p><p><a href="/bilder/schueler/tutorials-flucht-schule-aus-ausland-hinzufuegen.png"><img src="'+o+'" alt="Damit die Schule aus dem Ausland gewählt werden kann, muss dieser Eintrag einmalig in den Katalog Andere Schulen und Schulnummern aufgenommen werden." loading="lazy"></a></p><p><em>Damit die Schule aus dem Ausland gewählt werden kann, muss dieser Eintrag einmalig in den Katalog Andere Schulen und Schulnummern aufgenommen werden.</em></p><p>Erfassen Sie den vorherigen Schulbesuch, indem unter <em>&quot;Schüler ➜ Schulbesuch ➜ Vor der Aufnahme besuchte Schule/Einrichtung&quot;</em> diese Einträge vorgenommen werden:</p><ul><li><strong>Schulform</strong>: leer</li><li><strong>Name der Schule</strong>: <em>Schule aus dem sonstigen Ausland (999000)</em></li><li><strong>Allgemeine Herkunft des Schülers</strong>: <em>Ausländische Schüler, die aus dem Ausland zugezogen sind (Statistikkürzel AS)</em></li><li><strong>Entlassen am</strong>: Tatsächliches Ende des vorherigen Schulbesuchs nach den vorliegenden Unterlagen. Das Aufnahmedatum an Ihrer Schule ersetzt diesen Nachweis nicht.</li><li><strong>Entlassjahrgang</strong>.: leer</li><li><strong>Versetzung</strong>: <em>Schüler, die aus dem Ausland zugezogen sind (99)</em></li></ul>',26),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Eventuell lässt sich der Eintrag "),e("strong",null,"999000 Schule aus dem sonstigen Ausland"),n(' nicht anwählen. In diesem Fall muss diese "Schule" einmalig über '),e("em",null,"Kataloge ➜ Andere Schulen und Schulnummern"),n(" dem Katalog für wählbare Schulen hinzugefügt werden. Siehe hierzu den zweiten Screenshot.")]),e("p",null,"Dies gilt ebenfalls, sofern Schüler erstmals aus anderen Bundesländern oder anderen ausgewählten Ländern aufgenommen werden.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Bei einer erstmaligen Einschulung in Jahrgang "),e("strong",null,"01"),n(" wird die Herkunft als Einschulung erfasst. "),e("strong",null,"E1"),n(" bezeichnet zusätzlich das erste EP-Jahr, nicht den Jahrgang. Ein bereits erfolgter Schulbesuch darf nicht allein wegen der Aufnahme in Jahrgang 01 entfallen.")])],-1),i('<h2 id="zuordnung-zu-einer-klasse" tabindex="-1">Zuordnung zu einer Klasse <a class="header-anchor" href="#zuordnung-zu-einer-klasse" aria-label="Permalink to &quot;Zuordnung zu einer Klasse&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-flucht-5-klasse-anlegen.png"><img src="'+g+'" alt="Anlegen einer Internationalen Klasse über die Klassen- und Versetzungstabelle." loading="lazy"></a></p><p><em>Anlegen einer Internationalen Klasse über die Klassen- und Versetzungstabelle.</em></p><p>Flüchtlingskinder können entweder einer hierfür angelegten Klasse zugeordnet werden oder auf Regelklassen verteilt werden.</p><h3 id="zuordnung-zu-einer-eigenen-klasse" tabindex="-1">Zuordnung zu einer eigenen Klasse <a class="header-anchor" href="#zuordnung-zu-einer-eigenen-klasse" aria-label="Permalink to &quot;Zuordnung zu einer eigenen Klasse&quot;">​</a></h3><p>Es ist möglich, neu zugewanderte Schülerinnen und Schüler ausschließlich in eigenständigen Klassen in vollständig äußerer Differenzierung zu unterrichten. Die zugewanderten Schülerinnen und Schüler nehmen dann an keinem Unterricht der anderen Regelklassen teil, sondern bilden eine eigene Lerngruppe.</p><p>Über die Bezeichnung dieser Lerngruppen entscheidet die Schule.</p>',7),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,'Mögliche Bezeichnungen wären etwa "Vorbereitungsklasse", "Willkommensklasse" oder "Internationale Klasse".')],-1),e("p",null,[n("Im diesem Fall legen Sie in SchILD-NRW in der "),e("em",null,"Klassen-/Versetzungstabelle"),n(" eine eigene Klasse an.")],-1),e("p",null,"Vergeben Sie eine geeignete interne Bezeichnung (z.B. IK für internationale Klasse) und benennen Sie die Klasse in der Statistikbezeichnung mit einer Parallelität.",-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,'"JUA" steht im Beispiel für jahrgangsübergreifende Klasse der Parallelität A. Wenn Sie eine weitere internationale Klasse anlegen möchten, erhält diese in der Statistikbezeichnung das Kürzel JUB.')],-1),e("p",null,[n("Lassen Sie das Feld "),e("strong",null,"Jahrgang"),n(" leer.")],-1),e("p",null,[n("Tragen Sie als "),e("strong",null,"Folgeklasse"),n(" und "),e("strong",null,"Vorgängerklasse"),n(" die eigene, gerade erzeugte Klasse ein.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Speichern Sie die benannte Klasse zuerst mit der Häkchen-Taste oben links. Erst danach können Sie diese Klasse als Folge- und Vorgängerklasse auswählen.")],-1),i('<p>Wählen Sie eine passende <strong>Schulgliederung</strong>, etwa <em>&quot;GY9-G9&quot;</em>, <em>&quot;***-Standard für diese Schulform&quot;</em> etc.</p><p>Wählen Sie die für die tatsächliche Unterrichtsorganisation vorgesehene <strong>Klassenart</strong> aus dem aktuellen Katalog. Der ältere Screenshot verwendet die Bezeichnung <em>„Deutschförderklasse“</em> mit einem früheren Erlassverweis. Maßgeblich sind die aktuelle <a href="https://bass.schule.nrw/18425.htm" target="_blank" rel="noreferrer">BASS 13-63 Nr. 3</a> und die schulformspezifischen Erhebungsvorgaben.</p><p><a href="/bilder/schueler/tutorials-flucht-4-klassenart.png"><img src="'+c+'" alt="Zuordnung einer Klassenart in Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben." loading="lazy"></a></p><p><em>Zuordnung einer Klassenart in Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben.</em></p><p>Die in der <em>Klassen-/Versetzungstabelle</em> festgelegte <strong>Klassenart</strong> wird bei der entsprechenden Zuordnung in <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong> übernommen. Prüfen Sie dort den zum Lernabschnitt gehörenden Eintrag.</p><p>Sie finden die Angabe der Klassenart des aktuellen Halbjahres ebenfalls unter den aktuellen Laufbahndaten auf dem Reiter <em>Individualdaten I</em>.</p><p>Die Klasse für vollständig äußere Differenzierung ist für neu zugewanderte Lernende vorgesehen, die ausschließlich in der eigenen Lerngruppe unterrichtet werden. Entscheidend sind Unterrichtsorganisation und Deutschförderbedarf, nicht allein ein Fluchthintergrund.</p><h3 id="zuordnung-zu-den-regelklassen" tabindex="-1">Zuordnung zu den Regelklassen <a class="header-anchor" href="#zuordnung-zu-den-regelklassen" aria-label="Permalink to &quot;Zuordnung zu den Regelklassen&quot;">​</a></h3><p>Sollten die Flüchtlingskinder auf die <em>Regelklassen</em> der Schule verteilt sein und einzelne Deutschförderangebote erhalten, so bekommen die Schüler die <strong>Klassenart</strong> <em>&quot;Regelklasse&quot;</em>, so wie alle anderen Schüler auch.</p><p>Diese Schüler können dann entsprechend der oben ausgeführten und in den <em>Individualdaten II</em> gesetzten Bedingungen über den <em>Filter I</em> gefunden werden.</p><h2 id="fluchtlingskinder-in-der-grundschule" tabindex="-1">Flüchtlingskinder in der Grundschule <a class="header-anchor" href="#fluchtlingskinder-in-der-grundschule" aria-label="Permalink to &quot;Flüchtlingskinder in der Grundschule&quot;">​</a></h2><p>Trennen Sie auch hier den Jahrgang <strong>01 bis 04</strong> vom zusätzlichen <strong>EP-Jahr E1 bis E3</strong>. Die Zuordnung wird in den Jahrgängen 01 und 02 in jedem Halbjahr gepflegt; siehe <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">EP-Jahre</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eingabe_von_Fl%C3%BCchtlingskindern_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5487.</p>',14)])])}const w=a(m,[["render",f]]);export{_ as __pageData,w as default};
